INSERT INTO feature VALUES('incremental-parsing','syntax','Incremental re-parsing','total-parsing','implemented','notable',NULL,'An edit relabels around itself and re-molds only the top-level forms it touched. The tree lays each top-level form''s descendants out as one contiguous range of positions, which a stage keyed by form reads without a walk, and the commit takes each unchanged form up whole from the parse before it, one copy of its nodes, and joins only the forms the edit reached.','surface-syntax surface-parser surface-session','crates/surface-session/tests/edit.rs crates/surface-session/tests/forms.rs crates/surface-syntax/src/build.rs',NULL,NULL);
